const body = $json.body ?? $json;
const requestId = String(body.request_id ?? '').trim() || 'missing-request-id';
const rawText = String(body.raw_text ?? '').trim();

function normalizeQuery(input) {
  const cleaned = input
    .toLowerCase()
    .replace(/[“”]/g, '"')
    .replace(/[‘’]/g, "'")
    .replace(/[^a-z0-9\s'-]/g, ' ')
    .replace(/\b(i\s+want|i\s+would\s+like|please|can\s+i\s+have|find|search\s+for|show\s+me|print)\b/g, ' ')
    .replace(/\b(a|an|the)\b/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

  const base = cleaned || 'coloring page';
  return /\bcoloring\s+page\b/.test(base) ? base : `${base} coloring page`;
}

function plainHttpUrl(value) {
  if (!value || typeof value !== 'string') return null;
  const trimmed = value.trim();
  if (/\[[^\]]+\]\([^)]+\)/.test(trimmed)) return null;
  try {
    const url = new URL(trimmed);
    return url.protocol === 'http:' || url.protocol === 'https:' ? url.toString() : null;
  } catch {
    return null;
  }
}

function hostFrom(value) {
  const url = plainHttpUrl(value);
  if (!url) return 'unknown';
  try {
    return new URL(url).hostname.replace(/^www\./, '');
  } catch {
    return 'unknown';
  }
}

function inferContentType(url) {
  const lower = url.toLowerCase();
  if (lower.includes('.png')) return 'image/png';
  if (lower.includes('.webp')) return 'image/webp';
  if (lower.includes('.gif')) return 'image/gif';
  if (lower.includes('.svg')) return 'image/svg+xml';
  return 'image/jpeg';
}

function parseDimension(value, fallback) {
  const number = Number(value);
  return Number.isFinite(number) && number > 0 ? Math.round(number) : fallback;
}

function parseResolution(result) {
  const explicitWidth = parseDimension(result.width, 0);
  const explicitHeight = parseDimension(result.height, 0);
  if (explicitWidth && explicitHeight) {
    return { width: explicitWidth, height: explicitHeight };
  }

  const match = String(result.resolution ?? '').match(/(\d{2,5})\s*[x×]\s*(\d{2,5})/i);
  if (!match) return { width: 1200, height: 1600 };
  return {
    width: parseDimension(match[1], 1200),
    height: parseDimension(match[2], 1600),
  };
}

function titleFrom(result, index, query) {
  const candidate = String(result.title ?? result.content ?? '').replace(/\s+/g, ' ').trim();
  if (candidate) return candidate.slice(0, 120);
  return `${query} ${index + 1}`;
}

function mapImageResult(result, index, query) {
  const fullUrl = plainHttpUrl(result.img_src) ?? plainHttpUrl(result.url);
  if (!fullUrl) return null;

  const thumbnailUrl = plainHttpUrl(result.thumbnail_src) ?? fullUrl;
  const { width, height } = parseResolution(result);

  return {
    id: `img_${String(index + 1).padStart(2, '0')}`,
    title: titleFrom(result, index, query),
    source: hostFrom(result.source ?? result.url ?? fullUrl),
    thumbnail_url: thumbnailUrl,
    full_url: fullUrl,
    print_url: fullUrl,
    content_type: String(result.content_type ?? inferContentType(fullUrl)),
    width,
    height,
    printable: true,
  };
}

async function searchImages(query) {
  const baseUrl = process.env.SEARXNG_BASE_URL || 'http://searxng:8080';
  const url = new URL('/search', baseUrl);
  url.searchParams.set('q', query);
  url.searchParams.set('categories', 'images');
  url.searchParams.set('format', 'json');
  url.searchParams.set('safesearch', '2');
  url.searchParams.set('language', 'en');

  const response = await fetch(url, {
    headers: { Accept: 'application/json' },
    signal: AbortSignal.timeout(15000),
  });

  if (!response.ok) {
    throw new Error(`SearXNG image search failed with HTTP ${response.status}`);
  }

  const payload = await response.json();
  return Array.isArray(payload.results) ? payload.results : [];
}

const query = normalizeQuery(rawText);
let rawResults = [];

try {
  rawResults = await searchImages(query);
} catch (error) {
  console.warn(`Search failed for ${requestId}: ${error.message}`);
}

const images = rawResults
  .map((result, index) => mapImageResult(result, index, query))
  .filter(Boolean)
  .slice(0, 12);

return [{
  json: {
    request_id: requestId,
    query,
    images,
  },
}];
